output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Shopping carts are prohibited in one-cell-wide shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "A shopper must not push a cart into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "parked_cart_implies_single_file_errand",
    "text": "If a shopper sets down a cart in an open circulation aisle, they are obliged to enter a single-file shelf aisle on foot.",
    "abstraction": {
      "state_properties": {
        "openCirculationAisle": {
          "gt": [
            "freeWidthH",
            2
          ]
        },
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        }
      },
      "events": {
        "parkCartInOpenAisle": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              "openCirculationAisle"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "enterSingleFileOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartInOpenAisle",
      "discharge": "enterSingleFileOnFoot"
    }
  },
  {
    "id": "retrieve_cart_after_on_foot_shelf_pickup",
    "text": "After collecting an item on foot from a single-file shelf aisle, the shopper must return to and pick up the parked cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFileAisle",
            "adjShelf"
          ]
        },
        "openCirculationAisle": {
          "gt": [
            "freeWidthH",
            2
          ]
        }
      },
      "events": {
        "onFootShelfPickupInSingleFileAisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "singleFileShelfAisle"
            ]
          },
          "post": null
        },
        "pickUpParkedCartInOpenAisle": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT",
              "openCirculationAisle"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootShelfPickupInSingleFileAisle",
      "discharge": "pickUpParkedCartInOpenAisle"
    }
  },
  {
    "id": "no_on_foot_open_aisle_travel",
    "text": "Except when entering or leaving a narrow shelf aisle, shoppers should not walk from one open circulation aisle cell to another without their cart.",
    "abstraction": {
      "state_properties": {
        "openCirculationAisle": {
          "gt": [
            "freeWidthH",
            2
          ]
        }
      },
      "events": {
        "onFootOpenToOpenMove": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE",
              "openCirculationAisle"
            ]
          },
          "post": {
            "and": [
              {
                "not": "hasCart"
              },
              "openCirculationAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "onFootOpenToOpenMove"
    }
  },
  {
    "id": "no_open_shelf_shopping_without_cart",
    "text": "Items on shelves accessible from open aisles must not be picked up while separated from the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        },
        "openShelfAisle": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          "INTERACT",
          "openShelfAisle"
        ]
      }
    }
  },
  {
    "id": "must_take_entrance_cart",
    "text": "On entering the store, shoppers are obliged to acquire a cart from the entrance cart bay.",
    "abstraction": {
      "state_properties": {
        "entranceCartBay": "at(1,7)"
      },
      "events": {
        "takeEntranceCart": {
          "pre": {
            "and": [
              "entranceCartBay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "takeEntranceCart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "A shopper is prohibited from leaving the supermarket without their cart.",
    "abstraction": {
      "state_properties": {
        "exitCell": "at(11,7)"
      },
      "events": {
        "leaveStore": {
          "pre": {
            "and": [
              "exitCell",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leaveStore",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
